#pragma once
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* One file of the web UI bundle built into the app image. The table is
 * generated by CMakeLists.txt from ui-dist/ (ui_bundle.c in the build tree). */
typedef struct {
    const char *path; /* as requested, "/assets/x.js"; without ".gz" */
    const uint8_t *start;
    const uint8_t *end;
    bool gz; /* stored gzipped: send with Content-Encoding: gzip */
} espos_ui_file_t;

extern const espos_ui_file_t espos_ui_files[];
extern const size_t espos_ui_file_count;
